class Solution {
  private static final long MOD = 1_000_000_007L;

  private static long[][] mul(long[][] a, long[][] b) {
    long[][] c = new long[26][26];
    for (int i = 0; i < 26; i++) {
      for (int k = 0; k < 26; k++) {
        if (a[i][k] == 0) continue;
        for (int j = 0; j < 26; j++) c[i][j] = (c[i][j] + a[i][k] * b[k][j]) % MOD;
      }
    }
    return c;
  }

  public int lengthAfterTransformations(String s, int t, List<Integer> nums) {
    long[][] m = new long[26][26];
    for (int i = 0; i < 26; i++) {
      for (int k = 1; k <= nums.get(i); k++) m[i][(i + k) % 26] = 1;
    }
    long[][] r = new long[26][26];
    for (int i = 0; i < 26; i++) r[i][i] = 1;
    for (int e = t; e > 0; e >>= 1) {
      if ((e & 1) == 1) r = mul(r, m);
      m = mul(m, m);
    }
    long[] len = new long[26];
    for (int i = 0; i < 26; i++) {
      for (int j = 0; j < 26; j++) len[i] = (len[i] + r[i][j]) % MOD;
    }
    long ans = 0;
    for (int i = 0; i < s.length(); i++) ans += len[s.charAt(i) - 'a'];
    return (int) (ans % MOD);
  }
}
